mapper.select:
SELECT E.JOB_EXECUTION_ID FROM BATCH_JOB_EXECUTION E JOIN BATCH_JOB_INSTANCE I ON I.JOB_INSTANCE_ID = E.JOB_INSTANCE_ID
I.JOB_NAME = #{jobName}
 ORDER BY E.JOB_EXECUTION_ID DESC
 LIMIT #{limit}

SELECT I.JOB_NAME, E.STATUS, E.EXIT_CODE, E.EXIT_MESSAGE, E.START_TIME, E.END_TIME
  FROM BATCH_JOB_EXECUTION E JOIN BATCH_JOB_INSTANCE I ON I.JOB_INSTANCE_ID = E.JOB_INSTANCE_ID
 WHERE E.JOB_EXECUTION_ID = #{jobExecutionId}
